frappe.ui.form.on('Sales Invoice', {
    // Trigger when the form is loaded or refreshed
    refresh: function(frm) {
        handle_return_against(frm);
    },
});

function handle_return_against(frm) {
    // Check if the standard "Return Against" field has data
    if (frm.doc.return_against) {
        // Set the custom field value to 0
        frm.set_value('custom_is_paid', 0);

        // Hide the custom field
        frm.set_df_property('custom_is_paid', 'hidden', 1);
        frm.refresh_field('custom_is_paid');
    } else {
        // Optional: Show the field again if Return Against is empty
        frm.set_df_property('custom_is_paid', 'hidden', 0);
    }
}

function pi_item_code_query(item_group) {
    const filters = { has_variants: 0, disabled: 0 };
    if (item_group) filters.item_group = item_group;
    return { filters };
}

function sync_pi_item_queries(frm) {
    const query_fn = function (doc, cdt, cdn) {
        return pi_item_code_query(
            (locals[cdt] && locals[cdt][cdn] && locals[cdt][cdn].item_group) || ""
        );
    };

    // Standard frappe query
    frm.set_query("item_code", "items", query_fn);

    // Forcefully inject into the grid to override core ERPNext scripts
    const grid = frm.fields_dict.items && frm.fields_dict.items.grid;
    if (!grid) return;
    (grid.grid_rows || []).forEach((grid_row) => {
        const field = grid_row.fields_dict && grid_row.fields_dict.item_code;
        if (field) {
            field.get_query = function () {
                return pi_item_code_query((grid_row.doc && grid_row.doc.item_group) || "");
            };
        }
    });
}

frappe.ui.form.on("Purchase Invoice", {
    refresh: function (frm) {
        sync_pi_item_queries(frm);
    },
});

frappe.ui.form.on("Purchase Invoice Item", {
    item_group: function (frm, cdt, cdn) {
        const row = frappe.get_doc(cdt, cdn);

        // 1. Re-apply the query to the specific row
        const grid = frm.fields_dict.items && frm.fields_dict.items.grid;
        if (grid) {
            const grid_row = grid.grid_rows_by_docname && grid.grid_rows_by_docname[cdn];
            if (grid_row) {
                const field = grid_row.fields_dict && grid_row.fields_dict.item_code;
                if (field) {
                    field.get_query = function () {
                        return pi_item_code_query((row.item_group) || "");
                    };
                }
            }
        }

        // 2. SMART CLEAR: Only clear the item code if it doesn't belong to the newly selected group
        if (row.item_code) {
            frappe.db.get_value("Item", row.item_code, "item_group", function(r) {
                // If the item code's actual group doesn't match the row's new item_group, it means 
                // the user manually changed the group to look for something else. Clear it!
                if (r && r.item_group !== row.item_group) {
                    frappe.model.set_value(cdt, cdn, "item_code", "");
                }
            });
        }

        // 3. Refresh the grid to ensure the UI updates immediately
        frm.refresh_field("items");
    },
});
